    if (idl_st == OK && !idl_get(idl_rep, idl_m->n, &idl_o, 1023, 1, &idl_p0, &idl_l0))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && !idl_str_ok((const char *)idl_p0, idl_l0))
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_o != idl_m->n)
        idl_st = ERR_INTERNAL;
    if (idl_st == OK && idl_m->nh != 1)
        idl_st = ERR_INTERNAL;
    if (idl_st != OK) {
        idl_msg_drop(idl_m);
        return idl_st;
    }
    if (out_program)
        *out_program = idl_m->hs[0];
